using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class C1VisualBake{public static void Run(){string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string[] source={"Bandit","Scout","Lynx","Warden"},dest={"RuinsGuard","RuinsScout","RuinsElite","RuinsGuardian"};var stone=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/AncientRuins/Stone.mat");var gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/AncientRuins/Inlay.mat");for(int i=0;i<4;i++){var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CombatPrototype/Resources/CatWorld/Actors/"+source[i]+".prefab");if(original==null)throw new Exception("Existing legal cat source missing: "+source[i]);var model=(GameObject)PrefabUtility.InstantiatePrefab(original);model.name=dest[i];foreach(var r in model.GetComponentsInChildren<Renderer>()){bool eye=r.name.ToLowerInvariant().Contains("eye")||r.name.Contains("眼");r.sharedMaterial=eye?gold:stone;}PrefabUtility.SaveAsPrefabAsset(model,"Assets/CombatPrototype/Resources/CatWorld/Actors/"+dest[i]+".prefab");UnityEngine.Object.DestroyImmediate(model);}AssetDatabase.SaveAssets();File.WriteAllText(root+"/variants.json","{\"derivedCatPrefabs\":4,\"newExternalAssets\":0,\"animation\":\"existing rigid cat attachments and sampled animation reused\"}");EditorApplication.Exit(0);}}
